/* ===========================================================
 * 拼好码来自：https://discord.com/channels/1291925535324110879/1422717884378910801/1432380906613772309
 * SillyTavern CSS 美化模板
 * Skeleton V1
 *
 * 结构：
 * 01 · 全局控制
 * 02 · 顶栏
 * 03 · 底栏
 * 04 · 聊天区域
 * 05 · 滚动条 + 滑块
 * 06 · 输入框提示文字
 * 07 · 正则 + 脚本
 * 08 · 加载更多消息
 * 09 · 思维链
 * 10 · 收藏角色栏
 *
 * 使用原则：
 * 1. 每个元素只在固定模块中修改。
 * 2. 不要为了移动子元素而盲目修改父元素。
 * 3. 不确定控制关系时，先查元素字典。
 * 4. 不同视觉方案不要同时启用。
 * ============================================================ */


/* ============================================================
 * 01 · 全局控制
 * ============================================================ */


/* ------------------------------------------------------------
 * 01.01 · 外部字体
 * ------------------------------------------------------------ */

@import url("https://fontsapi.zeoseven.com/309/main/result.css");


/* ------------------------------------------------------------
 * 01.02 · 自定义字体
 * ------------------------------------------------------------ */

/*
@font-face {
    font-family: "字体名称";
    src: url("字体地址");
}
*/


/* ------------------------------------------------------------
 * 01.03 · 全局变量
 * ------------------------------------------------------------ */

:root {
    /* 主字体由 01.01 远程导入；功能界面保留系统字体。 */
    --garden-font-system: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
    --garden-font-ui: var(--garden-font-system);
    --garden-font-body: "KingHwaOldSong", "Songti SC", "Noto Serif CJK SC", serif;
    --garden-font-hint: var(--garden-font-body);
    --garden-page: #F8F7F3;
    --garden-chat-paper: rgba(248, 247, 243, 0.94);
    --garden-control: #F1F5F4;
    --garden-paper: rgba(255, 255, 255, 0.94);
    --garden-top: rgba(236, 242, 244, 0.96);
    /* v1.5：仅控制消息纸面背景的 alpha，不降低内容透明度。 */
    --char-message-opacity: 0.86;
    --user-message-opacity: 0.82;
    --garden-ai: rgba(255, 255, 255, var(--char-message-opacity));
    --garden-user: rgba(239, 244, 246, var(--user-message-opacity));
    --garden-line: #DCE3DE;
    --garden-ink: #46545B;
    --garden-icon: #637781;
    --garden-accent: #4F6B79;
    --garden-hover: #E7EFF1;
    --garden-hint: #707E85;
    --garden-radius: 16px;
    --garden-radius-small: 12px;
    --garden-shadow: 0 2px 10px rgba(67, 86, 78, 0.045);
}


/* ------------------------------------------------------------
 * 01.04 · 页面整体
 * ------------------------------------------------------------ */

body {
    font-family: var(--garden-font-ui);
    color: var(--garden-ink);
    background-color: var(--garden-page);
    text-shadow: none;
}


/* ------------------------------------------------------------
 * 01.05 · 全局弹出面板
 * ------------------------------------------------------------ */

.drawer-content {
    color: var(--garden-ink);
    background-color: var(--garden-paper);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius);
    box-shadow: var(--garden-shadow);
}


/* ------------------------------------------------------------
 * 01.06 · 表格抽屉
 * ------------------------------------------------------------ */

#table_drawer_content {
    color: var(--garden-ink);
    background-color: var(--garden-paper);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius);
    box-shadow: var(--garden-shadow);
}


/* ------------------------------------------------------------
 * 01.07 · 选项面板
 * ------------------------------------------------------------ */

.options-content {
    color: var(--garden-ink);
    background-color: var(--garden-paper);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius);
    box-shadow: var(--garden-shadow);
}

/* ------------------------------------------------------------
 * 01.08 · 面板内原生控件（v1.05）
 * selector 依据：SillyTavern release/public/style.css。
 * 仅改已知控件表面；不改开关、范围条、颜色选择器和状态按钮。
 * ------------------------------------------------------------ */

:is(.drawer-content, #table_drawer_content, .options-content)
:is(.text_pole:not([type="checkbox"], [type="radio"], [type="range"], [type="color"]), select, input[type="number"], .menu_button:not(.toggleable, .togglable, .api_button, .active)) {
    color: var(--garden-ink);
    background-color: var(--garden-control);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius-small);
    text-shadow: none;
}

:is(.drawer-content, #table_drawer_content, .options-content)
:is(.text_pole:not([type="checkbox"], [type="radio"], [type="range"], [type="color"]), select, input[type="number"], .menu_button:not(.toggleable, .togglable, .api_button, .active)):not(:disabled, [disabled], .disabled):hover {
    background-color: var(--garden-hover);
}

:is(.drawer-content, #table_drawer_content, .options-content)
:is(.text_pole:not([type="checkbox"], [type="radio"], [type="range"], [type="color"]), select, input[type="number"], .menu_button:not(.toggleable, .togglable, .api_button, .active)):focus-visible {
    border-color: var(--garden-icon);
    outline: 1px solid var(--garden-icon);
}

/* 原生下拉列表的未选项有独立深色规则；保留选中状态的细微区分。 */
:is(.drawer-content, #table_drawer_content, .options-content) select option {
    color: var(--garden-ink);
    background-color: #F8F7F3;
}

:is(.drawer-content, #table_drawer_content, .options-content) select option:checked {
    background-color: var(--garden-hover);
}


/* 角色编辑区：这两个原生 textarea 不带 .text_pole，需精确覆盖灰底。 */
#description_textarea,
#firstmessage_textarea {
    background-color: var(--garden-paper);
    color: var(--garden-ink);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius-small);
}

#description_textarea:focus,
#firstmessage_textarea:focus {
    border-color: #B8CCC9;
}

/* ------------------------------------------------------------
 * 01.09 · 原生分区 / 折叠标题（v1.06）
 * 已核对当前 DOM 与 style.css：这三组共用原生深色渐变。
 * 不覆盖聊天内标题或思维链；保留原生点击区、内边距和显隐。
 * ------------------------------------------------------------ */

#user-settings-block h4,
.drawer-content .standoutHeader,
.drawer-content :is(#extensions_settings, #extensions_settings2) .inline-drawer-toggle.inline-drawer-header {
    font-family: var(--garden-font-body);
    background-image: none;
    background-color: var(--garden-control);
    color: var(--garden-ink);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius-small);
    text-shadow: none;
}

/* 仅可折叠标题有交互反馈；up 是当前 DOM 的展开箭头状态。 */
.drawer-content .standoutHeader.inline-drawer-header:is(:hover, :focus-visible),
.drawer-content :is(#extensions_settings, #extensions_settings2) .inline-drawer-toggle.inline-drawer-header:is(:hover, :focus-visible) {
    background-color: var(--garden-hover);
    filter: none;
}

.drawer-content .standoutHeader.inline-drawer-header:has(.inline-drawer-icon.up),
.drawer-content :is(#extensions_settings, #extensions_settings2) .inline-drawer-toggle.inline-drawer-header:has(.inline-drawer-icon.up) {
    background-color: var(--garden-hover);
}


/* ============================================================
 * 02 · 顶栏
 * ============================================================ */


/* ------------------------------------------------------------
 * 02.01 · 顶栏整体
 * ------------------------------------------------------------ */

#top-settings-holder {
    background-color: var(--garden-top);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius);
    box-shadow: var(--garden-shadow);
}


/* ------------------------------------------------------------
 * 02.02 · 顶栏内部
 * ------------------------------------------------------------ */

#top-bar {
    /* 原生页面中与图标容器是独立层，自身也保留浅色纸面。 */
    background-color: var(--garden-top);
    border-color: transparent;
    border-radius: var(--garden-radius);
    box-shadow: none;
}


/* ------------------------------------------------------------
 * 02.03 · 顶栏通用图标
 * ------------------------------------------------------------ */

#top-settings-holder .drawer-icon {
    color: var(--garden-icon);
    text-shadow: none;
}


/* ------------------------------------------------------------
 * 02.04 · 顶栏图标图形
 *
 * 用于统一修改图标本体。
 * 如果使用不同图标，请在 02.06 中单独指定。
 * ------------------------------------------------------------ */

#top-settings-holder .drawer-icon::before {
}


/* ------------------------------------------------------------
 * 02.05 · 顶栏图标 Hover
 * ------------------------------------------------------------ */

#top-settings-holder .drawer-icon:hover::before {
    color: var(--garden-accent);
}


/* ------------------------------------------------------------
 * 02.06 · 顶栏单独图标
 *
 * 根据实际需要启用。
 *
 * AI 响应配置：
 * .drawer-icon.fa-sliders
 *
 * API：
 * .drawer-icon.fa-plug
 *
 * AI 回复格式化：
 * .drawer-icon.fa-font
 *
 * 世界信息：
 * .drawer-icon.fa-book-atlas
 *
 * 用户设置：
 * .drawer-icon.fa-user
 *
 * 背景图片：
 * .drawer-icon.fa-image
 *
 * 扩展：
 * .drawer-icon.fa-cubes
 *
 * 用户角色：
 * .drawer-icon.fa-face-smile
 *
 * 角色卡：
 * .drawer-icon.fa-address-card
 *
 * 记忆表格：
 * .drawer-icon.fa-bars-progress
 * ------------------------------------------------------------ */

/*
#top-settings-holder .drawer-icon.fa-sliders::before {
}

#top-settings-holder .drawer-icon.fa-plug::before {
}

#top-settings-holder .drawer-icon.fa-font::before {
}

#top-settings-holder .drawer-icon.fa-book-atlas::before {
}

#top-settings-holder .drawer-icon.fa-user::before {
}

#top-settings-holder .drawer-icon.fa-image::before {
}

#top-settings-holder .drawer-icon.fa-cubes::before {
}

#top-settings-holder .drawer-icon.fa-face-smile::before {
}

#top-settings-holder .drawer-icon.fa-address-card::before {
}

#top-settings-holder .drawer-icon.fa-bars-progress::before {
}
*/


/* ------------------------------------------------------------
 * 02.07 · 顶栏图标关闭状态
 * ------------------------------------------------------------ */

#top-settings-holder .drawer-icon.closedIcon::before {
}


/* ------------------------------------------------------------
 * 02.08 · 顶栏图标展开状态
 * ------------------------------------------------------------ */

#top-settings-holder .drawer-icon.openIcon::before {
    color: var(--garden-accent);
}


/* ============================================================
 * 03 · 底栏
 * ============================================================ */


/* ------------------------------------------------------------
 * 03.01 · 底栏整体
 * ------------------------------------------------------------ */

#send_form {
    color: var(--garden-ink);
    background-color: var(--garden-paper);
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius);
    box-shadow: var(--garden-shadow);
}

/* 去掉原生聚焦时叠加的外圈线，保留卡片边框和输入框进度顶边。 */
#send_form:has(#send_textarea:focus-visible) {
    outline: none;
}


/* ------------------------------------------------------------
 * 03.02 · 输入框
 * ------------------------------------------------------------ */

#send_textarea {
    font-family: var(--garden-font-body);
    color: var(--garden-ink);
    background-color: transparent;
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius-small);
    box-shadow: none;
    text-shadow: none;
    line-height: 1.65;
    caret-color: var(--garden-accent);
}

/* 聚焦仅加强细边线，保留原生键盘焦点轮廓。 */
#send_textarea:focus {
    border-color: var(--garden-icon);
}


/* ------------------------------------------------------------
 * 03.03 · 左侧菜单按钮
 * ------------------------------------------------------------ */

#options_button {
    color: var(--garden-icon);
    background-color: transparent;
    border-radius: var(--garden-radius-small);
    box-shadow: none;
    text-shadow: none;
}


/* ------------------------------------------------------------
 * 03.04 · 扩展按钮
 * ------------------------------------------------------------ */

#extensionsMenuButton {
    color: var(--garden-icon);
    background-color: transparent;
    border-radius: var(--garden-radius-small);
    box-shadow: none;
    text-shadow: none;
}


/* ------------------------------------------------------------
 * 03.05 · 快速回复按钮
 * ------------------------------------------------------------ */

#quick-reply-rocket-button {
    color: var(--garden-icon);
    background-color: transparent;
    border-radius: var(--garden-radius-small);
    box-shadow: none;
    text-shadow: none;
}


/* ------------------------------------------------------------
 * 03.06 · 发送按钮
 * ------------------------------------------------------------ */

#send_but {
    color: var(--garden-icon);
    background-color: transparent;
    border-radius: var(--garden-radius-small);
    box-shadow: none;
    text-shadow: none;
}


/* ------------------------------------------------------------
 * 03.07 · 发送按钮图标
 * ------------------------------------------------------------ */

#send_but::before {
}


/* ------------------------------------------------------------
 * 03.08 · 停止按钮
 * ------------------------------------------------------------ */

#mes_stop {
    color: var(--garden-icon);
    background-color: transparent;
    border-radius: var(--garden-radius-small);
    box-shadow: none;
    text-shadow: none;
}

/* 仅改变按钮底色，不改发送 / 停止及扩展的原生显隐。 */
#options_button:hover,
#extensionsMenuButton:hover,
#quick-reply-rocket-button:hover,
#send_but:hover,
#mes_stop:hover {
    background-color: var(--garden-hover);
}


/* ------------------------------------------------------------
 * 03.09 · 底栏通用图标
 *
 * 只有需要统一处理多个按钮图标时才使用。
 * ------------------------------------------------------------ */

/*
#send_form .fa-solid,
#send_form .fa-regular {
}
*/


/* ============================================================
 * 04 · 聊天区域
 * ============================================================ */


/* ------------------------------------------------------------
 * 04.01 · 聊天区域整体
 * ------------------------------------------------------------ */

#chat {
    color: var(--garden-ink);
    /* 纸面色不变；背景图天然位于底色之上、消息内容之下，不生成点击层。 */
    background-color: var(--garden-chat-paper);
    box-shadow: none;
    /* 透明常量底图只参与 alpha 混合，不产生可见渐变或新增素材。
     * v1.2：花5为蓝白主花（46%），叶1为大型底纹（11%），花1为粉色点缀（22%）。
     * 三层只在纸页边缘自然裁切，当前 Chromium 页面已临时预览验证。
     */
    background-image:
        -webkit-cross-fade(url("https://asterhost.pages.dev/i/20260924-5v0h1d2c2r2m59.webp"), linear-gradient(transparent, transparent), 54%),
        -webkit-cross-fade(url("https://asterhost.pages.dev/i/20260924-206m435m104l6k.webp"), linear-gradient(transparent, transparent), 89%),
        -webkit-cross-fade(url("https://asterhost.pages.dev/i/20260924-3w0y73152f133d.webp"), linear-gradient(transparent, transparent), 78%);
    background-repeat: no-repeat, no-repeat, no-repeat;
    background-size: 190px auto, 340px auto, 130px auto;
    background-position: left -105px top -42px, left -155px bottom -165px, right -32px bottom -38px;
    /* scroll 背景绑定滚动容器的可视纸面，不随内部消息内容滚走。 */
    background-attachment: scroll, scroll, scroll;
}

/* ============================================================
 * 04.02 · 单条消息
 * ============================================================ */


/* ------------------------------------------------------------
 * 04.02.01 · 消息整体
 *
 * 负责：
 * - 消息整体布局
 * - 消息整体尺寸
 * - 消息整体间距
 * - 消息整体背景
 * - 消息整体边框
 *
 * 不要在这里直接处理头像细节。
 * ------------------------------------------------------------ */

.mes {
    /* 外层只清除底色；保留原生排列，卡片外观交给 .mes_block。 */
    background-color: transparent;
}


/* ------------------------------------------------------------
 * 04.02.02 · 用户消息
 * ------------------------------------------------------------ */

.mes[is_user="true"] {
    --garden-message-paper: var(--garden-user);
}


/* ------------------------------------------------------------
 * 04.02.03 · AI / 角色消息
 * ------------------------------------------------------------ */

.mes[is_user="false"] {
    --garden-message-paper: var(--garden-ai);
}


/* ============================================================
 * 04.03 · 头像 + 元信息区域
 * ============================================================ */


/* ------------------------------------------------------------
 * 04.03.01 · 头像 / Token / 计时 / 楼层容器
 * ------------------------------------------------------------ */

.mesAvatarWrapper {
}


/* ------------------------------------------------------------
 * 04.03.02 · 头像容器
 * ------------------------------------------------------------ */

.avatar {
}

.mes[is_user="false"] .avatar,
.mes[is_user="true"] .avatar {
    position: relative;
}


/* ------------------------------------------------------------
 * 04.03.03 · 头像图片
 * ------------------------------------------------------------ */

.avatar img {
}


/* ------------------------------------------------------------
 * 04.03.04 · 头像装饰框
 * ------------------------------------------------------------ */

.avatar::after {
}

/* 仅为聊天头像叠加水彩框，不扩大点击区域或改变头像裁切。 */
.mes[is_user="false"] .avatar::after,
.mes[is_user="true"] .avatar::after {
    content: "";
    position: absolute;
    inset: -6px;
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    pointer-events: none;
}

.mes[is_user="false"] .avatar::after {
    background-image: url("https://asterhost.pages.dev/i/20260924-5c0t3p5i1h1q48.webp");
}

.mes[is_user="true"] .avatar::after {
    background-image: url("https://asterhost.pages.dev/i/20260924-0w2r4a0z2u323d.webp");
}


/* ------------------------------------------------------------
 * 04.03.05 · Token
 * ------------------------------------------------------------ */

.tokenCounterDisplay {
}


/* ------------------------------------------------------------
 * 04.03.06 · 回复计时
 * ------------------------------------------------------------ */

.mes_timer {
}


/* ------------------------------------------------------------
 * 04.03.07 · 楼层 / 消息 ID
 * ------------------------------------------------------------ */

.mesIDDisplay {
}


/* ============================================================
 * 04.04 · 消息主体
 * ============================================================ */


/* ------------------------------------------------------------
 * 04.04.01 · 消息主体容器
 * ------------------------------------------------------------ */

.mes_block {
    color: var(--garden-ink);
    background-color: var(--garden-message-paper, var(--garden-ai));
    border: 1px solid var(--garden-line);
    border-radius: var(--garden-radius);
    box-shadow: var(--garden-shadow);
    padding: 12px;
}


/* ------------------------------------------------------------
 * 04.04.02 · 消息头 / 名称区域
 * ------------------------------------------------------------ */

.ch_name {
}


/* ------------------------------------------------------------
 * 04.04.03 · 名称文字
 * ------------------------------------------------------------ */

.name_text {
    font-family: var(--garden-font-body);
}


/* ------------------------------------------------------------
 * 04.04.04 · 时间
 * ------------------------------------------------------------ */

.timestamp {
}


/* ------------------------------------------------------------
 * 04.04.05 · 消息操作按钮
 * ------------------------------------------------------------ */

.mes_buttons {
}


/* ------------------------------------------------------------
 * 04.04.06 · 消息正文
 * ------------------------------------------------------------ */

.mes_text {
    font-family: var(--garden-font-body);
    color: var(--garden-ink);
    line-height: 1.75;
    text-shadow: none;
}

/* v1.07：正文以消息卡片内容区为参照，左右留白由卡片统一提供。
 * 不再为头像列从正文宽度中扣除空间；保留上下内边距和原生消息结构。
 */
.mes:not(.smallSysMes) > .mes_block > .mes_text {
    box-sizing: border-box;
    width: 100%;
    padding-inline: 0;
}


/* ============================================================
 * 04.05 · Markdown / 正文细节
 * ============================================================ */


/* ------------------------------------------------------------
 * 04.05.01 · 普通段落
 * ------------------------------------------------------------ */

.mes_text p {
}


/* ------------------------------------------------------------
 * 04.05.02 · 引用
 * ------------------------------------------------------------ */

.mes_text q {
    color: #557A94;
    /* 当前正文为 500；同字重避免字体合成粗体，用色彩与浅底纹分层。 */
    background-image: linear-gradient(to bottom, transparent 58%, rgba(178, 207, 225, 0.24) 58%, rgba(178, 207, 225, 0.24) 91%, transparent 91%);
    border-radius: 2px;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
}


/* ------------------------------------------------------------
 * 04.05.03 · 心理文本 / 强调文本
 * ------------------------------------------------------------ */

.mes_text em {
    /* 心理活动 / 括号附加文字：作为轻淡的铅笔旁注。 */
    color: rgba(92, 108, 101, 0.58);
    font-size: 0.96em;
    font-style: italic;
    font-weight: normal;
}


/* ------------------------------------------------------------
 * 04.05.04 · 行内代码
 * ------------------------------------------------------------ */

.mes_text :not(pre) > code {
    background-color: rgba(214, 226, 223, 0.72);
    color: #59655F;
    padding: 0.08em 0.28em;
    border-radius: 4px;
    border-color: transparent;
    box-shadow: none;
}


/* ------------------------------------------------------------
 * 04.05.05 · 代码块
 * ------------------------------------------------------------ */

.mes_text pre {
}


/* ------------------------------------------------------------
 * 04.05.06 · Markdown 引用块
 * ------------------------------------------------------------ */

.mes_text blockquote {
}


/* ------------------------------------------------------------
 * 04.05.07 · 分割线
 * ------------------------------------------------------------ */

.mes_text hr {
}


/* ------------------------------------------------------------
 * 04.05.08 · 加粗
 * ------------------------------------------------------------ */

.mes_text strong {
}


/* ============================================================
 * 04.06 · 消息装饰
 * ============================================================ */


/* ------------------------------------------------------------
 * 04.06.01 · 消息主体前置装饰
 * ------------------------------------------------------------ */

.mes_block::before {
}


/* ------------------------------------------------------------
 * 04.06.02 · 消息主体后置装饰
 * ------------------------------------------------------------ */

.mes_block::after {
}


/* ------------------------------------------------------------
 * 04.06.03 · 消息整体前置装饰
 * ------------------------------------------------------------ */

.mes::before {
}


/* ------------------------------------------------------------
 * 04.06.04 · 消息整体后置装饰
 * ------------------------------------------------------------ */

.mes::after {
}


/* ============================================================
 * 05 · 滚动条 + 滑块
 * ============================================================ */


/* ------------------------------------------------------------
 * 05.01 · 浏览器滚动条整体
 * ------------------------------------------------------------ */

::-webkit-scrollbar {
}


/* ------------------------------------------------------------
 * 05.02 · 滚动条轨道
 * ------------------------------------------------------------ */

::-webkit-scrollbar-track {
}


/* ------------------------------------------------------------
 * 05.03 · 滚动条滑块
 * ------------------------------------------------------------ */

::-webkit-scrollbar-thumb {
}


/* ------------------------------------------------------------
