/* ============================================================
 * 05.05 · Range 滑块
 * ============================================================ */


/* ------------------------------------------------------------
 * 05.05.01 · Range 整体
 * ------------------------------------------------------------ */

:is(.drawer-content, #table_drawer_content, .options-content) input[type="range"] {
    /* 去除原生黑色内阴影与压暗滤镜；保留原生尺寸、appearance 和数值逻辑。 */
    --garden-range-track: #DFE8E3;
    --garden-range-thumb: #839D99;
    background-image: none;
    background-color: var(--garden-range-track);
    box-shadow: none;
    filter: none;
    accent-color: var(--garden-range-thumb);
}

:is(.drawer-content, #table_drawer_content, .options-content) input[type="range"]:is(:hover, :focus-visible) {
    --garden-range-track: #D5E1DB;
    --garden-range-thumb: #6D8985;
    filter: none;
}

:is(.drawer-content, #table_drawer_content, .options-content) input[type="range"]:focus-visible {
    outline: 1px solid var(--garden-icon);
    outline-offset: 3px;
}


/* ------------------------------------------------------------
 * 05.05.02 · WebKit 轨道
 * ------------------------------------------------------------ */

:is(.drawer-content, #table_drawer_content, .options-content) input[type="range"]::-webkit-slider-runnable-track {
    background-color: var(--garden-range-track);
    border-radius: var(--garden-radius-small);
    box-shadow: none;
}


/* ------------------------------------------------------------
 * 05.05.03 · WebKit 滑块
 * ------------------------------------------------------------ */

:is(.drawer-content, #table_drawer_content, .options-content) input[type="range"]::-webkit-slider-thumb {
    background-color: var(--garden-range-thumb);
    border-color: var(--garden-paper);
    box-shadow: none;
}


/* ------------------------------------------------------------
 * 05.05.04 · Firefox 轨道
 * ------------------------------------------------------------ */

:is(.drawer-content, #table_drawer_content, .options-content) input[type="range"]::-moz-range-track {
    background-color: var(--garden-range-track);
    border-color: var(--garden-line);
    border-radius: var(--garden-radius-small);
    box-shadow: none;
}


/* ------------------------------------------------------------
 * 05.05.05 · Firefox 滑块
 * ------------------------------------------------------------ */

:is(.drawer-content, #table_drawer_content, .options-content) input[type="range"]::-moz-range-thumb {
    background-color: var(--garden-range-thumb);
    border-color: var(--garden-paper);
    box-shadow: none;
}


