/* ===== CHAPTER CARD · MIST PAPER ===== */

.chapter-card {
    box-sizing: border-box;
    width: 100%;
    margin: 18px 0;
    padding: 20px;

    background: #eaf0f2 !important;
    border: 1px solid #cbd8dc !important;
    border-radius: 16px !important;

    color: #46545b !important;
    box-shadow: 0 4px 14px rgba(67, 86, 78, 0.06);

    font-family: var(--garden-font-body, serif);
    line-height: 1.8;
}

.chapter-card .chapter-eyebrow {
    margin-bottom: 8px;
    color: #8499a2 !important;
    font-family: var(--garden-font-ui, sans-serif);
    font-size: 11px !important;
    letter-spacing: 3px !important;
    text-transform: uppercase;
}

.chapter-card .chapter-num {
    margin-bottom: 4px;
    color: #8499a2 !important;
    font-family: var(--garden-font-ui, sans-serif);
    font-size: 14px !important;
    letter-spacing: 0.08em;
}

.chapter-card .chapter-title {
    margin: 18px 0 !important;
    color: #485e68 !important;
    background: transparent !important;
    font-size: 26px !important;
    font-weight: 600 !important;
    line-height: 1.5;
}

.chapter-card .chapter-divider {
    width: 100%;
    height: 1px;
    margin: 16px 0;
    background: linear-gradient(
        90deg,
        #aabcc3,
        rgba(170, 188, 195, 0.12)
    );
}

.chapter-card .chapter-brief {
    color: #4b5154 !important;
    font-size: 15px !important;
    line-height: 2 !important;
    overflow-wrap: anywhere;
}

.mes_text .chapter-card {
    background: #eaf0f2 !important;
    border: 3px solid #ff00ff !important;
    padding: 20px !important;
}

/* ===== CODA · ECHO AND THREAD ===== */

.coda-panel {
    box-sizing: border-box;
    width: 100%;
    margin: 16px 0;
    padding: 18px;
    background: #f4f5f3;
    border: 1px solid #d9dfda;
    border-radius: 12px;
    color: #4b5550;
    font-family: serif;
    font-size: 13px;
    line-height: 1.8;
}

.coda-header {
    display: flex;
    align-items: baseline;
    gap: 10px;
    padding-bottom: 12px;
    border-bottom: 1px solid #d9dfda;
}

.coda-label {
    color: #657c70;
    font-family: sans-serif;
    font-size: 18px;
    font-weight: 700;
    letter-spacing: 2px;
}

.coda-subtitle {
    color: #9aa59d;
    font-family: sans-serif;
    font-size: 10px;
    letter-spacing: 2px;
}

.coda-meta {
    display: grid;
    grid-template-columns: 1fr;
    gap: 8px;
    margin: 14px 0 20px;
}

.coda-meta-item {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.coda-key {
    color: #94a198;
    font-family: sans-serif;
    font-size: 10px;
    letter-spacing: 1.5px;
}

.coda-value {
    color: #53645a;
    font-size: 12px;
}

.coda-section {
    margin-top: 18px;
}

.coda-section-title {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 10px;
    color: #718679;
    font-family: sans-serif;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1.5px;
}

.coda-dot {
    width: 6px;
    height: 6px;
    flex-shrink: 0;
    border-radius: 50%;
    background: #8fa797;
}

.coda-text {
    color: #4b5550;
    font-size: 13px;
    line-height: 1.9;
    overflow-wrap: anywhere;
}

.coda-foreshadow {
    padding-top: 14px;
    border-top: 1px dashed #d4dcd5;
}

.coda-clue {
    display: flex;
    align-items: baseline;
    gap: 10px;
    margin: 9px 0;
}

.coda-index {
    flex-shrink: 0;
    color: #9aaa9e;
    font-family: sans-serif;
    font-size: 10px;
    letter-spacing: 1px;
}

.coda-clue-text {
    color: #58665d;
    font-size: 12px;
    line-height: 1.8;
    overflow-wrap: anywhere;
}

.coda-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 18px;
    padding-top: 10px;
    border-top: 1px solid #e0e5e0;
    color: #a0aaa2;
    font-family: sans-serif;
    font-size: 9px;
    letter-spacing: 2px;
}

.coda-footer span {
    color: #8fa797;
    font-size: 13px;
}
